  "items:sevenfold_crown_chain:description": "Sept couronnes brisées pendent d'une même chaîne — une pour chacun des Silencieux. Portée en travers de la poitrine du Sans-Couronne lui-même, jusqu'à ce qu'il choisisse de voyager plus léger.",
